<section class="page-hero container"><span class="eyebrow">YOUR COMMUNITY PROFILE</span><h1>Make it yours.</h1><p>Keep your name and general location up to date so local swaps are easier to arrange.</p></section><section class="container form-page"><div class="form-panel"><?php if($errors): ?><div class="form-errors"><?php foreach($errors as $err): ?><p><?= e($err) ?></p><?php endforeach; ?></div><?php endif; ?><form method="post" class="form-stack"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Full name<input name="name" required minlength="2" maxlength="80" value="<?= e($name) ?>"></label><label>Email address<input value="<?= e($user['email']) ?>" disabled><small>Email is read-only in this version.</small></label><label>City / area<input name="location" maxlength="120" value="<?= e($location) ?>" placeholder="e.g. Puducherry"><small>Do not enter your full home address.</small></label><button class="btn" type="submit">Save profile ↗</button></form></div></section><?php require __DIR__.'/includes/footer.php';?>
